#pragma once

#include <cstdint>
#include <span>
#include <string>
#include <unordered_map>
#include <vector>

namespace gpu::native
{
enum class ShaderStage : uint32_t { Vertex, Pixel };

struct NativeShader
{
    std::string name;
    ShaderStage stage;
    std::vector<uint8_t> virtualData, physicalData, dxil;
    std::string source;
    uint32_t textureMask=0;
    // Float constant registers the shader reads, [constantFirst,
    // constantEnd) of its stage's 256 (shader_catalog.cpp ConstantRange).
    uint16_t constantFirst=0,constantEnd=256;
};

// Immutable assets generated by the current patched XenosRecomp and DXC.
// Identity includes virtual metadata: identical code can have different constants.
class ShaderCatalog
{
public:
    static ShaderCatalog Load(const std::string& path);
    static ShaderCatalog Parse(std::span<const uint8_t> bytes);
    const NativeShader* Find(ShaderStage stage, std::span<const uint8_t> virtualData,
        std::span<const uint8_t> physicalData) const;
    const NativeShader* Find(const std::string& name, ShaderStage stage) const;
    const std::vector<NativeShader>& Shaders() const { return shaders; }

private:
    std::vector<NativeShader> shaders;
    std::unordered_map<std::string,size_t> namedShaders;
};

class ShaderObjects
{
public:
    // Every initialization replaces the previous binding, even if unknown.
    const NativeShader* Register(uint32_t object, ShaderStage stage,
        std::span<const uint8_t> virtualData, std::span<const uint8_t> physicalData,
        const ShaderCatalog& catalog);
    const NativeShader* Find(uint32_t object, ShaderStage stage) const;

private:
    std::unordered_map<uint32_t, const NativeShader*> objects;
};
}
